import base64, html, os, secrets, json
from typing import Any
from fastapi import APIRouter, Header, HTTPException, Query
from fastapi.responses import HTMLResponse
from pydantic import BaseModel
from database import Database
router=APIRouter()
STAGES=[("NEW","🔎 Discovered"),("VERIFIED","🧹 Verified"),("QUALIFIED","🎯 Qualified"),("RESEARCHED","📋 Researched"),("MESSAGE_GENERATED","✉️ Message generated"),("CONTACTED","📤 Contacted"),("RESPONDED","💬 Replied"),("MEETING","📅 Meeting"),("PROPOSAL","📄 Proposal"),("WON","💰 Won"),("LOST","❌ Lost")]
def auth(v):
 u,p=os.getenv('DASHBOARD_USER','').strip(),os.getenv('DASHBOARD_PASSWORD','').strip()
 if not u or not p or not v or not v.startswith('Basic '): return False
 try:
  a,b=base64.b64decode(v[6:]).decode().split(':',1); return secrets.compare_digest(a,u) and secrets.compare_digest(b,p)
 except Exception:return False
def req(v):
 if not auth(v): raise HTTPException(401,'Dashboard authentication required',headers={'WWW-Authenticate':'Basic'})
class Status(BaseModel): status:str
def e(v):return html.escape(str(v if v is not None else ''),quote=True)
def js(v):return json.dumps(v,ensure_ascii=False)
@router.get('/dashboard',response_class=HTMLResponse)
async def dashboard(authorization:str|None=Header(default=None)):
 req(authorization); db=Database(); stats=await db.today_stats(); history=await db.history(14)
 return HTMLResponse(PAGE.replace('__STATS__',js(stats)).replace('__HISTORY__',js(history)).replace('__STAGES__',js(STAGES)))
@router.get('/dashboard/api/leads')
async def leads(authorization:str|None=Header(default=None),priority:str|None=None,limit:int=Query(500,ge=1,le=1000),offset:int=Query(0,ge=0)):
 req(authorization); db=Database(); rows=await db.list_leads(priority,limit,offset)
 out=[]
 for x in rows:
  try:r=await db.get_research(int(x['id']))
  except Exception:r={}
  try:a=await db.activities(int(x['id']),20)
  except Exception:a=[]
  out.append({**x,'research':r or {},'activities':a or []})
 return {'ok':True,'leads':out,'count':len(out)}
@router.patch('/dashboard/api/leads/{business_id}/status')
async def status(business_id:int,payload:Status,authorization:str|None=Header(default=None)):
 req(authorization)
 if payload.status not in {x[0] for x in STAGES}: raise HTTPException(400,'Invalid status')
 db=Database(); await db.set_status(business_id,payload.status); await db.record_activity(business_id,'STATUS_'+payload.status,'dashboard','Status changed from dashboard'); return {'ok':True,'status':payload.status}
PAGE=r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#071426"><title>LeadHunter · Lead Intelligence</title><style>
:root{color-scheme:dark;--bg:#06101d;--panel:#0b1b2e;--panel2:#0e233b;--line:#274766;--text:#f5f8ff;--muted:#8fa8c5;--cyan:#20d8ff;--violet:#8b5cf6;--green:#19d487;--yellow:#ffd43b;--orange:#ff9d3d;--red:#ff5b6e;--pink:#f05bb5}*{box-sizing:border-box}html,body{margin:0;overflow-x:hidden;background:radial-gradient(900px 500px at 0 0,#2c176c55,transparent 65%),radial-gradient(700px 500px at 100% 0,#087e9c33,transparent 65%),var(--bg);color:var(--text);font:14px/1.45 Inter,system-ui,sans-serif}button,input,select{font:inherit}button{cursor:pointer}a{text-decoration:none;color:inherit}.app{min-height:100dvh;display:grid;grid-template-columns:230px minmax(0,1fr)}aside{position:sticky;top:0;height:100dvh;padding:16px 12px;background:#050d18ee;border-right:1px solid var(--line)}.brand{display:flex;gap:10px;align-items:center;padding:4px 7px 18px}.logo{width:43px;height:43px;border-radius:14px;display:grid;place-items:center;background:linear-gradient(135deg,#7c3aed,#06b6d4);font-size:22px}.brand b{font-size:18px}.brand small{display:block;color:var(--muted)}nav{display:grid;gap:4px}nav button{border:0;background:transparent;color:#9fb2ca;text-align:left;padding:11px;border-radius:11px}nav button.active,nav button:hover{background:#132b48;color:#fff}.main{min-width:0;padding:24px clamp(10px,3vw,40px) 50px}.top{display:flex;justify-content:space-between;gap:15px;align-items:flex-start}.eyebrow{color:var(--cyan);font-size:10px;font-weight:900;letter-spacing:.15em}.top h1{font-size:clamp(28px,4vw,42px);margin:4px 0;line-height:1.05}.muted{color:var(--muted)}.actions{display:flex;gap:7px}.btn{border:1px solid #315272;background:#0d2036;color:#fff;border-radius:11px;padding:10px 13px}.primary{border:0;background:linear-gradient(135deg,#7c3aed,#06b6d4);font-weight:800}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:16px 0}.stat{border:1px solid var(--line);border-radius:15px;padding:11px;background:linear-gradient(145deg,#112842,#09182a);display:flex;gap:9px;align-items:center}.stat i{font-style:normal;font-size:20px}.stat small{display:block;color:#8ea7c2;font-size:9px}.stat strong{font-size:21px}.toolbar{border:1px solid var(--line);background:#08182aee;border-radius:18px;padding:11px;margin-bottom:10px}.search{display:flex;gap:7px}.search input{flex:1;min-width:0;background:#051222;border:1px solid #2a4a69;color:#fff;border-radius:11px;padding:11px}.filters{display:flex;gap:6px;overflow:auto;margin-top:8px}.filter{white-space:nowrap;border:1px solid #2a4968;background:#0b1d32;color:#9eb2ca;padding:7px 10px;border-radius:99px}.filter.active{background:#30205f;border-color:#805bdc;color:#fff}.lead{border:1px solid var(--line);border-radius:17px;background:linear-gradient(145deg,#0c2138,#071629);margin:8px 0;overflow:hidden}.lead.open{border-color:#805bdc}.summary{display:grid;grid-template-columns:minmax(0,2.2fr) 120px 90px 75px 110px 30px;gap:7px;align-items:center;padding:12px;min-height:68px;cursor:pointer}.name{font-weight:850;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.sub{color:#8ba4c0;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.score{font-weight:900;color:var(--yellow)}.priority{font-size:10px;border:1px solid #34516d;border-radius:99px;padding:5px 8px;text-align:center}.hot{color:var(--orange);border-color:#704d2d;background:#2b1d0f}.chev{color:#8ca3bd}.open .chev{transform:rotate(180deg)}.details{display:none;border-top:1px solid #25445f;padding:10px}.open .details{display:block}.hero{border:1px solid #7657c5;border-radius:15px;padding:14px;background:radial-gradient(500px 160px at 0 0,#633cc533,transparent 70%),#0a1b2e}.hero h2{margin:0;font-size:20px}.hero-meta{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}.badge{border:1px solid #315473;background:#102742;border-radius:99px;padding:6px 9px;font-size:11px}.badge.scoreb{color:var(--yellow);border-color:#735c1e;background:#2a220e}.importance{margin-top:10px;display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.imp{padding:10px;border-radius:12px;border:1px solid #284965;background:#07182b}.imp b{display:block;font-size:9px;color:#7f9ab8;text-transform:uppercase;letter-spacing:.1em}.imp strong{display:block;margin-top:2px;font-size:16px}.good{color:var(--green)}.bad{color:var(--red)}.warn{color:var(--yellow)}.section{margin-top:9px;border:1px solid #254562;border-radius:14px;background:#071629;padding:12px}.section h3{margin:0 0 9px;font-size:10px;letter-spacing:.13em;color:#86a0bc}.facts{display:grid;grid-template-columns:100px minmax(0,1fr);gap:7px}.facts b{color:#7893b1;font-size:11px}.facts span{overflow-wrap:anywhere}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:9px}.chips{display:flex;flex-wrap:wrap;gap:6px}.chip{padding:6px 8px;border-radius:9px;border:1px solid #6549a8;background:#211944;color:#e4dcff;font-size:11px}.evidence{display:grid;gap:6px}.evidence div{display:flex;gap:8px;align-items:flex-start;border-radius:10px;padding:8px 9px;background:#0d2238;border:1px solid #254966}.evidence .ico{width:22px}.rank{display:flex;align-items:center;gap:12px}.ranknum{font-size:32px;font-weight:950;color:var(--cyan)}.rank small{display:block;color:#829bb8}.bar{height:7px;background:#142c45;border-radius:99px;overflow:hidden;margin-top:6px}.bar i{display:block;height:100%;background:linear-gradient(90deg,#8b5cf6,#06d8ff);width:0}.services{display:flex;flex-wrap:wrap;gap:6px}.service{padding:7px 9px;background:#092e32;border:1px solid #1a806f;border-radius:9px;color:#a9f4df;font-size:11px}.stage{display:flex;gap:7px}.stage select{flex:1;background:#0b2037;color:#fff;border:1px solid #315371;border-radius:10px;padding:9px}.links{display:flex;flex-wrap:wrap;gap:7px}.link{padding:8px 10px;border:1px solid #345575;background:#0d233b;border-radius:10px;font-size:11px}.link:hover{border-color:#8b5cf6}.telegram{background:#103252;border:1px solid #28577d;border-radius:15px 15px 15px 5px;padding:12px;position:relative}.telegram:after{content:'';position:absolute;left:-1px;bottom:-7px;border-width:7px 7px 0 0;border-style:solid;border-color:#28577d transparent transparent}.telegram p{white-space:pre-wrap;margin:0;color:#dbe8f7}.telegram time{display:block;text-align:right;color:#89a2be;font-size:10px;margin-top:7px}.activity{display:grid;gap:6px}.act{border-left:3px solid #7657c5;padding:7px 9px;background:#0d2035;border-radius:0 9px 9px 0}.act small{color:#7892af}.view{display:none}.view.active{display:block}.empty{padding:35px;text-align:center;color:#849db8}.toast{position:fixed;right:15px;bottom:15px;padding:10px 13px;background:#132b45;border:1px solid #3a5b7b;border-radius:10px;opacity:0;transition:.2s}.toast.show{opacity:1}
@media(max-width:950px){.stats{grid-template-columns:repeat(3,1fr)}.summary{grid-template-columns:minmax(0,2fr) 100px 70px 38px 25px}.summary .priority{display:none}}
@media(max-width:700px){.app{display:block}aside{height:auto;position:relative;padding:8px 8px 7px;border-right:0;border-bottom:1px solid var(--line)}.brand{padding:2px 5px 8px}.brand small{font-size:10px}nav{display:flex;overflow:auto;gap:3px}nav button{white-space:nowrap;flex:0 0 auto;padding:8px 10px}.main{padding:10px 7px 35px}.top{display:block}.top h1{font-size:29px}.actions{display:grid;grid-template-columns:1fr 1fr;margin-top:9px}.stats{grid-template-columns:repeat(2,1fr);gap:6px;margin:10px 0}.stat{padding:9px 7px}.stat i{font-size:18px}.stat strong{font-size:19px}.toolbar{padding:9px;border-radius:15px}.summary{grid-template-columns:minmax(0,1fr) 66px 25px;gap:6px;padding:10px;min-height:62px}.summary .sub,.summary .priority{display:none}.score{font-size:13px}.details{padding:8px}.hero{padding:12px}.hero h2{font-size:18px}.importance{grid-template-columns:repeat(3,1fr);gap:5px}.imp{padding:8px 6px}.imp strong{font-size:14px}.grid2{grid-template-columns:1fr}.facts{grid-template-columns:82px minmax(0,1fr)}.section{padding:10px}.ranknum{font-size:28px}.link{flex:1;text-align:center}.stage select{font-size:12px}}
</style></head><body><div class="app"><aside><div class="brand"><div class="logo">🚀</div><div><b>LeadHunter</b><small>Lead intelligence</small></div></div><nav><button class="active" onclick="view('leads',this)">🏠 Leads</button><button onclick="view('find',this)">🔎 Find / Filter</button><button onclick="view('analytics',this)">📊 Analytics</button><button onclick="view('outreach',this)">💬 Outreach</button><button onclick="view('settings',this)">⚙️ Settings</button></nav></aside><main class="main"><div class="view active" id="leads"><header class="top"><div><div class="eyebrow">LEAD INTELLIGENCE</div><h1>Important data first.</h1><div class="muted">Every lead shows the evidence, Google visibility, opportunity and pitch reason.</div></div><div class="actions"><button class="btn" onclick="load()">↻ Refresh</button><button class="btn primary" onclick="focusSearch()">＋ Search leads</button></div></header><div class="stats" id="stats"></div><div class="toolbar"><div class="search"><input id="q" placeholder="Search business, city, category, service…" oninput="render()"></div><div class="filters"><button class="filter active" data-p="" onclick="priority(this,'')">All</button><button class="filter" data-p="HOT" onclick="priority(this,'HOT')">🔥 Hot</button><button class="filter" data-p="WARM" onclick="priority(this,'WARM')">🟡 Warm</button></div></div><div id="list"></div></div><div class="view" id="find"><div class="viewcard"><h2>🔎 Find / Filter</h2><p>Use the lead search above to search business name, city, category, problems, services and research evidence.</p><button class="btn primary" onclick="view('leads',document.querySelector('nav button'))">Open lead workspace</button></div></div><div class="view" id="analytics"><div class="viewcard"><h2>📊 Analytics</h2><p>Daily pipeline activity is available below the lead workspace. Lead intelligence remains the primary view so important evidence is never buried.</p><div id="hist"></div></div></div><div class="view" id="outreach"><div class="viewcard"><h2>💬 Outreach</h2><p>Select a lead and use its outreach action. This workspace is intentionally lightweight until a message provider is connected.</p><div class="empty">Open a lead → create outreach.</div></div></div><div class="view" id="settings"><div class="viewcard"><h2>⚙️ Settings</h2><p>Dashboard preferences.</p><label>Compact mode <input type="checkbox" onchange="document.body.classList.toggle('compact',this.checked)"></label></div></div></main></div><div class="toast" id="toast"></div><script>
const DATA=__STATS__,HISTORY=__HISTORY__,STAGES=__STAGES__;let leads=[],prio='',openId=null;const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));const val=(o,...ks)=>{for(const k of ks){if(o&&o[k]!=null&&o[k]!=='' )return o[k]}return null};
function view(id,b){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));if(b)b.classList.add('active');if(id==='analytics')history()}
function focusSearch(){document.getElementById('q').focus()}
function priority(b,p){prio=p;document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');load()}
async function load(){try{const u='/dashboard/api/leads?limit=500'+(prio?'&priority='+encodeURIComponent(prio):'');const r=await fetch(u);const j=await r.json();leads=j.leads||[];render()}catch(e){toast('Could not load leads')}}
function renderStats(){const d=DATA;const a=[['🔎','Leads',leads.length],['🎯','Qualified',d.qualified||0],['🔥','Hot',d.hot_leads||0],['📤','Contacted',d.contacted||0],['💬','Replies',d.replies||0],['📅','Meetings',d.meetings||0],['📄','Proposals',d.proposals||0],['💰','Won',d.won||0]];document.getElementById('stats').innerHTML=a.map(x=>`<div class="stat"><i>${x[0]}</i><div><small>${x[1]}</small><strong>${x[2]}</strong></div></div>`).join('')}
function render(){renderStats();const q=document.getElementById('q').value.toLowerCase().trim();let a=leads.filter(l=>{const r=l.research||{};const z=JSON.stringify(l)+' '+JSON.stringify(r);return !q||z.toLowerCase().includes(q)});document.getElementById('list').innerHTML=a.map(card).join('')||'<div class="empty">No leads match this search.</div>';if(openId)document.getElementById('lead-'+openId)?.classList.add('open')}
function card(l){const score=Number(l.score||0),hot=score>=80||l.priority==='HOT',r=l.research||{},g=r.google||{},s=r.search||{},loc=r.local||{},rank=val(g,'local_rank','rank'),rating=val(g,'rating'),reviews=val(g,'review_count'),website=val(l,'website')||'';return `<article class="lead ${openId==l.id?'open':''}" id="lead-${l.id}"><div class="summary" onclick="toggle(${l.id})"><div><div class="name">🏢 ${esc(l.name||'Unnamed business')}</div><div class="sub">📍 ${esc(l.city||'—')} · ${esc(l.industry||'—')}</div></div><div class="score">${score}/100</div><div class="rating">${rating?'⭐ '+esc(rating):'—'}</div><div class="priority ${hot?'hot':''}">${hot?'🔥 HOT':esc(l.priority||'—')}</div><button class="btn" style="padding:6px" onclick="event.stopPropagation();google(${l.id})">🔎</button><span class="chev">⌄</span></div><div class="details">${detail(l,r,g,s,loc,rank,rating,reviews,website)}</div></article>`}
function detail(l,r,g,s,loc,rank,rating,reviews,website){const score=Number(l.score||0),phone=val(l,'phone')||val(loc,'phone')||((loc.phones||[])[0]),email=val(l,'email')||val(loc,'email')||((loc.emails||[])[0]),probs=l.problems||r.problems||[],services=l.recommended_services||[],profiles=r.profiles||{};let profileLinks=Object.entries(profiles).flatMap(([k,v])=>(Array.isArray(v)?v:[v]).slice(0,2).map(u=>`<a class="link" target="_blank" href="${esc(u)}">🌐 ${esc(k.replace('_',' '))}</a>`)).join('');const maps=val(g,'maps_url')||val(l,'google_maps_url');const query=val(s,'query')||`${l.industry||'business'} in ${l.city||''}`;const note=probs.length?probs.slice(0,8).map(x=>'• '+x).join('\n'):'No major problem recorded.';const last=(l.activities||[])[0];return `<div class="hero"><h2>${esc(l.name||'Unnamed')}</h2><div class="hero-meta"><span class="badge">📍 ${esc(l.city||'—')}</span><span class="badge">🏢 ${esc(l.industry||'—')}</span><span class="badge scoreb">🎯 ${score}/100 · ${esc(l.priority||'—')}</span></div><div class="importance"><div class="imp"><b>Google local</b><strong class="${rank?'good':'warn'}">${rank?'#'+esc(rank):'Not measured'}</strong></div><div class="imp"><b>Rating</b><strong>${rating?'⭐ '+esc(rating):'—'}</strong></div><div class="imp"><b>Reviews</b><strong>${reviews??'—'}</strong></div></div></div><div class="section"><h3>🚨 VERIFIED LEAD EVIDENCE</h3><div class="evidence"><div><span class="ico">🌐</span><span><b>Website</b><br><span class="${website?'good':'bad'}">${website?'✅ '+esc(website):'❌ No verified official website was found'}</span></span></div><div><span class="ico">📞</span><span><b>Phone</b><br><span class="${phone?'good':'bad'}">${phone?'✅ '+esc(phone):'❌ No public business phone was found in researched sources'}</span></span></div><div><span class="ico">✉️</span><span><b>Email</b><br><span class="${email?'good':'bad'}">${email?'✅ '+esc(email):'❌ No public business email was found in researched sources'}</span></span></div></div></div><div class="grid2"><div class="section"><h3>📍 GOOGLE VISIBILITY</h3><div class="rank"><div class="ranknum">${rank?'#'+esc(rank):'—'}</div><div><b>Local search position</b><small>${rank?'for '+esc(query):'Google local position was not measured'}</small>${rank?`<div class="bar"><i style="width:${Math.max(5,100-Math.min(95,Number(rank)*5))}%"></i></div>`:''}</div></div><div class="facts" style="margin-top:10px"><b>Organic</b><span>Not measured</span><b>Maps</b><span>${maps?'Available':'Not found'}</span></div></div><div class="section"><h3>💡 WHY THIS LEAD MATTERS</h3><div class="telegram"><p>${esc(probs.length?probs.slice(0,6).join('\n'):note)}</p><time>Research evidence</time></div></div></div><div class="section"><h3>🎯 RECOMMENDED SERVICES / PITCH</h3><div class="services">${services.length?services.map(x=>`<span class="service">✨ ${esc(x)}</span>`).join(''):'<span class="muted">No recommended services recorded.</span>'}</div></div><div class="section"><h3>📋 BUSINESS DETAILS</h3><div class="facts"><b>Business</b><span>${esc(l.name||'—')}</span><b>Category</b><span>${esc(l.industry||'—')}</span><b>Location</b><span>${esc(l.city||'—')}</span><b>Source</b><span>${esc(l.source||'—')}</span><b>Updated</b><span>${esc(l.updated_at||l.created_at||'—')}</span></div></div><div class="section"><h3>🎯 LEAD STAGE</h3><div class="stage"><select onchange="setStatus(${l.id},this.value)">${STAGES.map(x=>`<option value="${x[0]}" ${l.status===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select><span class="badge">${esc(l.status||'NEW')}</span></div></div><div class="section"><h3>💬 NOTES & ACTIVITY</h3><div class="telegram"><p>${esc(note)}</p><time>${last?esc(last.action+' · '+(last.created_at||'')):'Research notes'}</time></div>${(l.activities||[]).length?'<div class="activity" style="margin-top:9px">'+l.activities.slice(0,8).map(a=>`<div class="act"><b>${esc(a.action||'Activity')}</b><br><small>${esc(a.channel||'system')} · ${esc(a.created_at||'')}</small><br>${esc(a.notes||'')}</div>`).join('')+'</div>':''}</div><div class="section"><h3>🔗 QUICK RESEARCH — LINKS</h3><div class="links">${maps?`<a class="link" target="_blank" href="${esc(maps)}">📍 Google Maps</a>`:''}<a class="link" target="_blank" href="https://www.google.com/search?q=${encodeURIComponent((l.name||'')+' '+(l.city||''))}">🔎 Google Search</a>${website?`<a class="link" target="_blank" href="${esc(website)}">🌐 Website</a>`:''}${profileLinks}</div></div><div class="actions"><button class="btn primary" onclick="outreach(${l.id})">✉️ Create outreach</button><button class="btn" onclick="toggle(${l.id})">Collapse</button></div>`}
function toggle(id){openId=openId===id?null:id;render()}
function google(id){const l=leads.find(x=>x.id==id);if(l)window.open('https://www.google.com/search?q='+encodeURIComponent((l.name||'')+' '+(l.city||'')),'_blank')}
async function setStatus(id,status){try{const r=await fetch('/dashboard/api/leads/'+id+'/status',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});if(!r.ok)throw 0;const l=leads.find(x=>x.id==id);if(l)l.status=status;toast('Stage updated')}catch(e){toast('Could not update stage')}}
function outreach(id){const l=leads.find(x=>x.id==id);if(!l)return;const msg=`Hi ${l.name||'there'},\n\nI noticed a few online growth opportunities for your business in ${l.city||'your area'}. I would be happy to share the findings and a practical plan.\n\nWould you be open to a quick chat?`;navigator.clipboard?.writeText(msg);toast('Outreach message copied')}function toast(t){const x=document.getElementById('toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),1800)}function history(){document.getElementById('hist').innerHTML='<div class="section"><h3>LAST 14 DAYS</h3>'+HISTORY.map(x=>`<div class="act"><b>${esc(x.date||'')}</b> · 🔎 ${x.leads_found||0} leads · 🎯 ${x.qualified||0} qualified · 📤 ${x.contacted||0} contacted · 💬 ${x.replies||0} replies · 📅 ${x.meetings||0} meetings · 💰 ${x.won||0} won</div>`).join('')+'</div>'}load();
</script></body></html>'''
